  @Deprecated('This member is deprecated and will be removed in a future version')
  Future<List<NewsModel>> getNewsList();

  Stream<List<NewsModel>> loadNewsFeed(NewsFeedFilter filter);

  Future<void> saveNewsList(List<NewsModel> value);
}
```

### 2. lib/data/repository_impl/news_repository_impl.dart
Полная замена файла с cache-then-network:

```dart
import 'package:mad_flutter_practicum/domain/datasource/db_datasource.dart';
import 'package:mad_flutter_practicum/domain/datasource/rest_datasource.dart';
import 'package:mad_flutter_practicum/domain/model/news_filter.dart';
import 'package:mad_flutter_practicum/domain/model/news_model.dart';
import 'package:mad_flutter_practicum/domain/repository/news_repository.dart';

class NewsRepositoryImpl implements NewsRepository {
  const NewsRepositoryImpl(this._restDatasource, this._dbDatasource);

  final RestDatasource _restDatasource;
  final DbDatasource _dbDatasource;

  @override
  @Deprecated('This member is deprecated and will be removed in a future version')
  Future<List<NewsModel>> getNewsList() => _restDatasource.getNewsList();

  @override
  Stream<List<NewsModel>> loadNewsFeed(NewsFeedFilter filter) async* {
    // Эмитим кэш мгновенно (первый эмит)
    yield await _dbDatasource.getNewsList().catchError((_) => <NewsModel>[]);

    // Параллельно запрашиваем сеть и эмитим обновлённый список (второй эмит)
    final fresh = filter.forceRefresh ? await _restDatasource.getNewsList() : await _dbDatasource.getNewsList();
    if (filter.forceRefresh) {
      await _dbDatasource.saveNewsList(fresh);
    }
    yield fresh;
  }

  @override
  Future<void> saveNewsList(List<NewsModel> value) => _dbDatasource.saveNewsList(value);
}
```

### 3. lib/app/news_list/news_list_page.dart
Полная замена файла — StreamBuilder вместо FutureBuilder:

```dart
import 'package:flutter/material.dart';
import 'package:mad_flutter_practicum/app/app.dart';
import 'package:mad_flutter_practicum/domain/domain.dart';

import 'widgets/widgets.dart';

class NewsListPage extends StatefulWidget {
  const NewsListPage({super.key});

  @override
  State<NewsListPage> createState() => _NewsListPageState();
}

class _NewsListPageState extends State<NewsListPage> with SingleTickerProviderStateMixin {
  static final _tween = Tween<double>(begin: 0.25, end: 1);

  late Stream<List<NewsModel>> _newsStream;

  late final AnimationController _scaleController;
  late final Animation<double> _scaleAnimation;
  bool _animationPlayed = false;

  @override
  void initState() {
    super.initState();
    _initAnimation();
    _initData();
  }

  @override
  void dispose() {
    _scaleController.dispose();
    super.dispose();
  }

  void _initAnimation() {
    _scaleController = AnimationController(
      vsync: this,
      duration: Duration(milliseconds: 200),
    );
    _scaleAnimation = _tween.animate(_scaleController);
  }

  void _initData() {
    final newsRepository = context.read<NewsRepository>();

    _newsStream = newsRepository.loadNewsFeed(const NewsFeedFilter(forceRefresh: true));

    // Запускаем анимацию при первом появлении данных (при первом эмите — кэше)
    _newsStream.first.then((_) {
      if (mounted && !_animationPlayed) {
        setState(() => _animationPlayed = true);
        _scaleController.forward();
      }
    });
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: Text(context.loc.news)),
      body: StreamBuilder<List<NewsModel>>(
        stream: _newsStream,
        builder: (BuildContext context, AsyncSnapshot<List<NewsModel>> snapshot) {
          final List<NewsModel>? data = snapshot.data;
          if (data == null || data.isEmpty) return const Center(child: CircularProgressIndicator());

          return ScaleTransition(
            scale: _scaleAnimation,
            child: ListView.builder(
              itemCount: data.length,
              itemBuilder: (BuildContext context, int index) {
                final NewsModel news = data[index];

                return Padding(
                  key: ValueKey(news.link),
                  padding: index == 0 ? EdgeInsets.zero : const EdgeInsets.only(top: 16),
                  child: NewsCard(model: news),
                );
              },
              padding: const EdgeInsets.fromLTRB(22, 16, 22, 40),
            ),
          );
        },
      ),
    );
  }
}
```

### 4. test/widget/news_list_page_test.dart
Полная замена файла — mock возвращает Stream вместо Future:

```dart
import 'package:flutter_test/flutter_test.dart';
import 'package:intl/date_symbol_data_local.dart';
import 'package:mad_flutter_practicum/app/app.dart';
import 'package:mad_flutter_practicum/domain/domain.dart';
import 'package:mockito/mockito.dart';

import '../mocks/repository.mocks.dart';

import 'widget.dart';

Future<void> main() async {
  await initializeDateFormatting(AppConstants.ruLocale, null);

  group('NewsListPage', () {
    final MockNewsRepository mockNewsRepository = MockNewsRepository();

    final newsItems = [
      NewsModel(title: 'Заголовок 1', link: 'https://example.com/1', date: DateTime.now()),
      NewsModel(title: 'Заголовок 2', link: 'https://example.com/2', date: DateTime.now()),
    ];

    setUp(() {
      when(mockNewsRepository.loadNewsFeed(any)).thenAnswer((_) async* {
        yield newsItems; // кэш
        yield newsItems; // сеть
      });
    });

    testWidgets('should display all news items when loaded', (WidgetTester tester) async {
      await tester.pumpWidget(
        buildWidget(
          providers: [
            Provider<NewsRepository>.value(value: mockNewsRepository),
          ],
          child: const NewsListPage(),
        ),
      );

      await tester.pumpAndSettle();

      expect(find.text('Заголовок 1'), findsOneWidget);
      expect(find.text('Заголовок 2'), findsOneWidget);
      expect(find.text('Заголовок 3'), findsNothing);
    });
  });
}
```

