      ];

      when(mockRestDatasource.getNewsList()).thenAnswer((_) async => newsList);

      final result = await repository.getNewsList();

      expect(result, newsList);
      verify(mockRestDatasource.getNewsList()).called(1);
    });

    test('loadNewsFeed with forceRefresh reads from network and caches', () async {
      final newsList = [
        NewsModel(title: 'Свежая новость', link: 'https://example.com/fresh', date: DateTime.now()),
      ];
      when(mockDbDatasource.getNewsList()).thenAnswer((_) async => <NewsModel>[]);
      when(mockRestDatasource.getNewsList()).thenAnswer((_) async => newsList);

      final stream = repository.loadNewsFeed(const NewsFeedFilter(forceRefresh: true));
      final results = await stream.toList();

      expect(results.last, newsList);
      verify(mockRestDatasource.getNewsList()).called(1);
      verify(mockDbDatasource.saveNewsList(newsList)).called(1);
    });

    test('loadNewsFeed without forceRefresh reads only from cache', () async {
      final cached = [
        NewsModel(title: 'Из кэша', link: 'https://example.com/cached', date: DateTime.now()),
      ];
      when(mockDbDatasource.getNewsList()).thenAnswer((_) async => cached);

      final stream = repository.loadNewsFeed(NewsFeedFilter.all);
      final results = await stream.toList();

      expect(results.first, cached);
      verify(mockDbDatasource.getNewsList()).called(2);
      verifyNever(mockRestDatasource.getNewsList());
    });

    test('should complete successfully when saveNewsList is called', () async {
      final newsList = [
        NewsModel(title: 'Заголовок 1', link: 'https://example.com/1', date: DateTime.now()),
      ];

      await repository.saveNewsList(newsList);

      verify(mockDbDatasource.saveNewsList(newsList)).called(1);
    });
  });

  group('SettingsRepository', () {
    late SettingsRepository settingsRepository;

    setUp(() {
      settingsRepository = SettingsRepositoryImpl(mockPreferenceDatasource);
    });

    test('should complete initialization without errors', () async {
      when(mockPreferenceDatasource.getToken()).thenAnswer((_) => Future.value('my-token'));

      await settingsRepository.initAsyncData();

      verify(settingsRepository.initAsyncData()).called(1);
    });
