      when(mockPreferenceDatasource.readThemeMode()).thenReturn(AppThemeMode.system);

      final result = settingsRepository.readThemeMode();

      expect(result, AppThemeMode.system);
    });

    test('should emit theme mode changes through stream', () {
      when(mockPreferenceDatasource.themeModeStream).thenAnswer((_) => Stream.fromIterable([AppThemeMode.light]));

      expect(settingsRepository.themeModeStream, emitsInOrder([AppThemeMode.light]));
    });

    test('should emit auth state changes through stream', () {
      when(mockPreferenceDatasource.isAuthStream).thenAnswer((_) => Stream.fromIterable([true, false]));

      expect(settingsRepository.isAuthStream, emitsInOrder([true, false]));
    });
  });
